var i=`1096-num-ansom-chek`;var n=`world-1096`;var t=`KH`;var o=`southeast-asia`;var r=8;var s=275;var l={en:`Num Ansom Chek`,ua:`Нум ансом чек`};var u={en:`Num Ansom Chek is a dish from Cambodia prepared with glutinous rice, banana, coconut milk, banana leaf. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Нум ансом чек, страва кухні країни Камбоджа, яку готують із таких продуктів: клейкий рис, банан, кокосове молоко, банановий лист. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var m=[{en:`Soak the measured rice or noodles in clean cool water for about 200 minutes, then drain and proceed to the specified cooking step.`,ua:`Замочіть зазначені рис або локшину в чистій прохолодній воді близько 200 хвилин, злийте і переходьте до подальшого готування.`,t:[`rice-soaking`],m:200,i:[[`glutinous-rice`,420,`g`],[`water`,980,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`banana`,5,`pcs`],[`coconut-milk`,200,`ml`],[`palm-sugar`,75,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:14,i:[[`banana-leaf`,8,`leaf`]]},{en:`Steam the already prepared parcels or mixture over gently boiling water for approximately 55 minutes, until fully cooked or set.`,ua:`Готуйте раніше підготовлені згортки або масу на парі над слабким кипінням близько 55 хвилин до готовності.`,t:[`steaming`],m:55,i:[]}];var d={slug:i,id:n,country:`KH`,region:o,servings:8,minutes:275,title:l,text:u,steps:m};export{t as country,d as default,n as id,s as minutes,o as region,r as servings,i as slug,m as steps,u as text,l as title};